class Scope(val parent: Scope?) {
    private val symbols = mutableMapOf<String, Symbol>()
    fun define(name: String, sym: Symbol): Boolean = symbols.putIfAbsent(name, sym) == null
    fun lookup(name: String): Symbol? {                     // innermost outward
        var s: Scope? = this
        while (s != null) { s.symbols[name]?.let { return it }; s = s.parent }
        return null
    }
}
